```ts
type ParsedTrack =
	| {type: 'fixed'; size: number}
	| {type: 'fr'; size: number}
	| {type: 'auto'}
	| {type: 'minmaxFixed'; min: number; max: number}
	| {type: 'minmaxFr'; min: number; fr: number};

const parseTracks = (template?: string): ParsedTrack[] => {
	if (!template || template.trim() === '') {
		return [];
	}

	return template.trim().split(/\s+/).map(parseTrack);
};

const parseTrack = (token: string): ParsedTrack => {
	const track = token.trim();

	if (track === 'auto') {
		return {type: 'auto'};
	}

	const fr = /^(\d+(?:\.\d+)?)fr$/.exec(track);
	if (fr) {
		return {type: 'fr', size: Number.parseFloat(fr[1])};
	}

	if (/^\d+(\.\d+)?$/.test(track)) {
		return {type: 'fixed', size: Math.floor(Number.parseFloat(track))};
	}

	const minmax = /^minmax\(\s*([^,]+?)\s*,\s*([^)]+?)\s*\)$/.exec(track);
	if (minmax) {
		const min = Math.max(0, Math.floor(Number.parseFloat(minmax[1])));
		const maxFr = /^(\d+(?:\.\d+)?)fr$/.exec(minmax[2].trim());
		if (maxFr) {
			return {type: 'minmaxFr', min, fr: Number.parseFloat(maxFr[1])};
		}

		const max = Math.max(min, Math.floor(Number.parseFloat(minmax[2])));
		return {type: 'minmaxFixed', min, max};
	}

	// Unknown token — treat as auto
	return {type: 'auto'};
};
