type Placement = {start: number; end: number};

const parsePlacement = (value: string | number | undefined): Placement | undefined => {
	if (value === undefined || value === '') {
		return undefined;
	}

	if (typeof value === 'number') {
		const start = Math.max(1, Math.floor(value));
		return {start, end: start};
	}

	const range = /^\s*(\d+)\s*\/\s*(\d+)\s*$/.exec(value);
	if (range) {
		const start = Math.max(1, Number.parseInt(range[1], 10));
		const end = Math.max(start, Number.parseInt(range[2], 10));
		return {start, end};
	}

	const single = Number.parseInt(value, 10);
	if (Number.isFinite(single)) {
		const start = Math.max(1, single);
		return {start, end: start};
	}

	return undefined;
};
