Next, the core part: `src/grid.ts`. I'll write it carefully.

```ts
import Yoga, {type Node as YogaNode} from 'yoga-layout';
import {type DOMElement} from './dom.js';

/*
Grid layout for boxes with `display: grid`.

Yoga doesn't support grid layout, so after the normal flexbox pass, we:
1. Find all grid containers.
2. For each container (deepest first): measure the natural size of each item,
   compute track sizes and item placement, then override each item's yoga node
   with absolute position and size, and if the user didn't specify one, give
   the container explicit width/height.
3. Reset items whose parent is no longer a grid container.
4. Re-layout from the root so the grid sizes propagate to ancestors.
*/

type Track =
	| {type: 'fixed'; size: number}
	| {type: 'fr'; size: number}
	| {type: 'auto'}
	| {type: 'minmaxFixed'; min: number; max: number}
	| {type: 'minmaxFr'; min: number; fr: number};

const parseTrack = (token: string): Track => {
	const track = token.trim();

	if (track === 'auto') {
		return {type: 'auto'};
	}

	const fr = /^(\d+(?:\.\d+)?)fr$/.exec(track);
	if (fr) {
		return {type: 'fr', size: Number.parseFloat(fr[1])};
	}

	if (/^\d+(\.\d+)?$/.test(track)) {
		return {type: 'fixed', size: Math.floor(Number.parseFloat(track))};
	}

	const minmax = /^minmax\(\s*([^,]+?)\s*,\s*([^)]+?)\s*\)$/.exec(track);
	if (minmax) {
		const min = Math.max(0, Math.floor(Number.parseFloat(minmax[1].trim())));
		const maxFr = /^(\d+(?:\.\d+)?)fr$/.exec(minmax[2].trim());
		if (maxFr) {
			return {type: 'minmaxFr', min, fr: Number.parseFloat(maxFr[1])};
		}

		const max = Math.max(min, Math.floor(Number.parseFloat(minmax[2].trim())));
		return {type: 'minmaxFixed', min, max};
	}

	// Unknown track size — treat as auto
	return {type: 'auto'};
};

const parseTracks = (template: string | undefined): Track[] => {
	if (!template) {
		return [];
	}

	const tokens = template.trim().split(/\s+/);
	return tokens.length > 0 ? tokens.map(parseTrack) : [];
};

type Placement = {
	start: number;
	end: number;
};

const parsePlacement = (
	value: string | number | undefined,
): Placement | undefined => {
	if (value === undefined || value === '') {
		return undefined;
	}

	let start: number;
	let end: number;

	if (typeof value === 'number') {
		start = Math.max(1, Math.floor(value));
		end = start;
	} else {
		const range = /^\s*(\d+)\s*\/\s*(\d+)\s*$/.exec(value);
		if (range) {
			start = Math.max(1, Number.parseInt(range[1], 10));
			end = Math.max(start, Number.parseInt(range[2], 10));
		} else {
			const index = Number.parseInt(value, 10);
			if (!Number.isInteger(index)) {
				return undefined;
			}

			start = Math.max(1, index);
			end = start;
		}
	}

	return {start, end};
};
```

Wait — Number.parseInt("2.5") = 2 → integer. I'm using parseInt, so "2.5" becomes 2. OK.

Next, the main part. Let me also handle `frWeight`:

```ts
const trackFr = (track: Track): number => {
	switch (track.type) {
		case 'fr':
			return track.size;
		case 'minmaxFr':
			return track.fr;
		default:
			return 0;
	}
};
```

Track sizing:

```ts
const sizeTracks = (
	tracks: Track[],
	contentSizes: number[],
	space: number,
	gap: number,
): number[] => {
	const count = tracks.length;
	const sizes = new Array<number>(count);
	let fixedTotal = 0;

	for (let i = 0; i < count; i++) {
		const track = tracks[i];

		switch (track.type) {
			case 'fixed':
				sizes[i] = track.size;
				break;
			case 'minmaxFixed':
				// A definite maximum makes the track a fixed-size one (shrinking to min is not supported)
				sizes[i] = track.max;
				break;
			case 'auto':
				sizes[i] = Math.max(0, Math.floor(contentSizes[i] ?? 0));
				break;
			case 'fr':
				sizes[i] = 0;
				break;
			case 'minmaxFr':
				sizes[i] = track.min;
				break;
		}

		fixedTotal += sizes[i];
	}

	const gapTotal = count > 1 ? gap * (count - 1) : 0;
	const remaining = Math.max(0, Math.floor(space) - fixedTotal - gapTotal);

	if (remaining > 0) {
		const totalFr = tracks.reduce((sum, track) => sum + trackFr(track), 0);

		if (totalFr > 0) {
			const shares = new Array<number>(count).fill(0);
			let allocated = 0;

			for (let i = 0; i < count; i++) {
				const weight = trackFr(tracks[i]);
				if (weight <= 0) continue;
				const exact = (remaining * weight) / totalFr;
				shares[i] = Math.floor(exact);
				allocated += shares[i];
			}

			// Largest-remainder method to get the sum of sizes exactly matching `remaining`
			const leftover = remaining - allocated;
			if (leftover > 0) {
				const order = tracks
					.map((_, index) => index)
					.filter(index => trackFr(tracks[index]) > 0)
					.sort((a, b) => {
						const remainderA = (remaining * trackFr(tracks[a])) / totalFr - shares[a];
						const remainderB = (remaining * trackFr(tracks[b])) / totalFr - shares[b];
						if (remainderB !== remainderA) {
							return remainderB - remainderA;
						}
						return a - b;
					});

				for (const index of order.slice(0, leftover)) {
					shares[index]++;
				}
			}

			for (let i = 0; i < count; i++) {
				sizes[i] += shares[i];
			}
		}
	}

	return sizes;
};
```

Cell/placement — as designed. Item type:

```ts
type Item = {
	node: DOMElement;
	yoga: YogaNode;
	column: Placement | undefined;
	row: Placement | undefined;
	width: number;
	height: number;
};
```

Grid container layout:

```ts
const layoutGridContainer = (container: DOMElement): void => {
	const yogaNode = container.yogaNode!;
	const style = container.style;

	const columnTracks = parseTracks(style.gridTemplateColumns);
	const rowTracks = parseTracks(style.gridTemplateRows);

	const columnGap = Math.max(0, style.columnGap ?? style.gap ?? 0);
	const rowGap = Math.max(0, style.rowGap ?? style.gap ?? 0);

	const padding = {
		top: yogaNode.getComputedPadding(Yoga.EDGE_TOP),
		right: yogaNode.getComputedPadding(Yoga.EDGE_RIGHT),
		bottom: yogaNode.getComputedPadding(Yoga.EDGE_BOTTOM),
		left: yogaNode.getComputedPadding(Yoga.EDGE_LEFT),
	};
	const border = {
		top: yogaNode.getComputedBorder(Yoga.EDGE_TOP),
		right: yogaNode.getComputedBorder(Yoga.EDGE_RIGHT),
		bottom: yogaNode.getComputedBorder(Yoga.EDGE_BOTTOM),
		left: yogaNode.getComputedBorder(Yoga.EDGE_LEFT),
	};

	const contentWidth = Math.max(
		0,
		yogaNode.getComputedWidth() - padding.left - padding.right - border.left - border.right,
	);
	const contentHeight = Math.max(
		0,
		yogaNode.getComputedHeight() - padding.top - padding.bottom - border.top - border.bottom,
	);

	// Collect grid items and measure their natural (content) sizes
	const items: Item[] = [];

	for (const child of container.childNodes) {
		if (child.nodeName === '#text' || !child.yogaNode) {
			continue;
		}

		const element = child as DOMElement;

		if (element.yogaNode.getDisplay() === Yoga.DISPLAY_NONE) {
			continue;
		}

		const item: Item = {
			node: element,
			yoga: element.yogaNode,
			column: parsePlacement(element.style.gridColumn),
			row: parsePlacement(element.style.gridRow),
			width: 0,
			height: 0,
		};

		// Previous grid pass may have sized this item to its cell.
		// Restore auto sizing so we measure its content
		if (element.internal_gridItem) {
			if (typeof element.style.width === 'undefined') {
				item.yoga.setWidthAuto();
			}

			if (typeof element.style.height === 'undefined') {
				item.yoga.setHeightAuto();
			}
		}

		item.yoga.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
		item.width = Math.max(0, Math.floor(item.yoga.getComputedWidth()));
		item.height = Math.max(0, Math.floor(item.yoga.getComputedHeight()));

		items.push(item);
	}

	// Place items: explicit placement wins, the rest flows row by row
	const wrapColumn = Math.max(columnTracks.length, 1);

	const occupied = new Set<string>();
	const cellKey = (row: number, column: number): string => `${row}:${column}`;

	const isFree = (row: number, startColumn: number, endColumn: number): boolean => {
		for (let column = startColumn; column <= endColumn; column++) {
			if (occupied.has(cellKey(row, column))) {
				return false;
			}
		}

		return true;
	};

	type Cell = {
		rowStart: number;
		rowEnd: number;
		colStart: number;
		colEnd: number;
	};

	const cells: Cell[] = new Array<Cell>(items.length);
	let cursorRow = 1;
	let cursorColumn = 1;

	for (let i = 0; i < items.length; i++) {
		const item = items[i];
		let cell: Cell;

		if (item.column && item.row) {
			cell = {
				colStart: item.column.start,
				colEnd: item.column.end,
				rowStart: item.row.start,
				rowEnd: item.row.end,
			};
		} else if (item.column) {
			const {start: colStart, end: colEnd} = item.column;
			let row = cursorRow;
			while (!isFree(row, colStart, colEnd)) {
				row++;
			}

			cell = {colStart, colEnd, rowStart: row, rowEnd: row};
		} else if (item.row) {
			const {start: rowStart, end: rowEnd} = item.row;
			let column = cursorColumn > wrapColumn ? 1 : cursorColumn;
			while (
				column < wrapColumn &&
				!isFreeSpan(rowStart, rowEnd, column)
			) {
				column++;
			}

			cell = {colStart: column, colEnd: column, rowStart, rowEnd};
		} else {
			let rowStart = cursorRow;
			let colStart = cursorColumn;

			while (occupied.has(cellKey(rowStart, colStart)) || colStart > wrapColumn) {
				colStart++;

				if (colStart > wrapColumn) {
					colStart = 1;
					rowStart++;
				}
			}

			cell = {colStart, colEnd: colStart, rowStart, rowEnd: rowStart};
		}

		for (let row = cell.rowStart; row <= cell.rowEnd; row++) {
			for (let column = cell.colStart; column <= cell.colEnd; column++) {
				occupied.add(cellKey(row, column));
			}
		}

		cells[i] = cell;

		if (cell.rowStart > cursorRow || (cell.rowStart === cursorRow && cell.colStart >= cursorColumn)) {
			cursorRow = cell.rowEnd;
			cursorColumn = cell.colEnd + 1;

			if (cursorColumn > wrapColumn) {
				cursorColumn = 1;
				cursorRow++;
			}
		}
	}
```

