```ts
const isGridContainer = (node: DOMElement): boolean =>
	node.style.display === 'grid' &&
	node.yogaNode !== undefined &&
	node.yogaNode.getDisplay() !== Yoga.DISPLAY_NONE;

const resetGridItem = (node: DOMElement): void => {
	node.internal_gridItem = false;

	const yoga = node.yogaNode;
	if (!yoga) {
		return;
	}

	if (typeof node.style.width === 'undefined') {
		yoga.setWidthAuto();
	}

	if (typeof node.style.height === 'undefined') {
		yoga.setHeightAuto();
	}

	for (const [edge, key] of [
		[Yoga.EDGE_LEFT, 'left'],
		[Yoga.EDGE_TOP, 'top'],
		[Yoga.EDGE_RIGHT, 'right'],
		[Yoga.EDGE_BOTTOM, 'bottom'],
	] as const) {
		if (typeof node.style[key] === 'undefined') {
			yoga.setPosition(edge, Number.NaN);
		}
	}

	if (node.style.position === 'absolute') {
		yoga.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
	} else if (node.style.position === 'static') {
