type Track =
	| {type: 'fixed'; size: number}
	| {type: 'fr'; size: number}
	| {type: 'auto'}
	| {type: 'minmaxFixed'; min: number; max: number}
	| {type: 'minmaxFr'; min: number; fr: number};

