			let column = cursorColumn > wrapColumn ? 1 : cursorColumn;

			while (column < wrapColumn && !isFree(rowStart, rowEnd, column, column)) {
				column++;
			}

			cell = {colStart: column, colEnd: column, rowStart, rowEnd};
		} else {
			let rowStart = cursorRow;
			let colStart = cursorColumn;

			while (
				occupied.has(cellKey(rowStart, colStart)) ||
				colStart > wrapColumn
			) {
				colStart++;

				if (colStart > wrapColumn) {
					colStart = 1;
					rowStart++;
				}
			}

			cell = {colStart, colEnd: colStart, rowStart, rowEnd: rowStart};
		}

		for (let row = cell.rowStart; row <= cell.rowEnd; row++) {
			for (let column = cell.colStart; column <= cell.colEnd; column++) {
				occupied.add(cellKey(row, column));
			}
		}

		cells[i] = cell;

		// Advance the auto-placement cursor past the placed cell (row-major)
		if (
			cell.rowStart > cursorRow ||
			(cell.rowStart === cursorRow && cell.colStart >= cursorColumn)
		) {
			cursorRow = cell.rowEnd;
			cursorColumn = cell.colEnd + 1;

			if (cursorColumn > wrapColumn) {
				cursorColumn = 1;
				cursorRow++;
			}
		}
	}

	// Count the tracks — auto-generated ones are created as needed
	let numColumns = columnTracks.length;
	let numRows = rowTracks.length;

	for (const cell of cells) {
		numColumns = Math.max(numColumns, cell.colEnd);
		numRows = Math.max(numRows, cell.rowEnd);
	}

	const fullColumnTracks: Track[] = [];

	for (let i = 0; i < numColumns; i++) {
		fullColumnTracks.push(columnTracks[i] ?? {type: 'auto'});
	}

	const fullRowTracks: Track[] = [];

	for (let i = 0; i < numRows; i++) {
		fullRowTracks.push(rowTracks[i] ?? {type: 'auto'});
	}

	// Content size of each track, used by `auto` tracks. Items spanning
	// multiple tracks contribute their size divided evenly across them.
	const columnContent = new Array<number>(numColumns).fill(0);
	const rowContent = new Array<number>(numRows).fill(0);

	for (let i = 0; i < items.length; i++) {
		const cell = cells[i];
		const columnSpan = cell.colEnd - cell.colStart + 1;
		const rowSpan = cell.rowEnd - cell.rowStart + 1;
		const widthPerColumn = columnSpan > 0 ? items[i].width / columnSpan : 0;
		const heightPerRow = rowSpan > 0 ? items[i].height / rowSpan : 0;

		for (let column = cell.colStart; column <= cell.colEnd; column++) {
			columnContent[column - 1] = Math.max(
				columnContent[column - 1],
				Math.ceil(widthPerColumn),
			);
		}

		for (let row = cell.rowStart; row <= cell.rowEnd; row++) {
			rowContent[row - 1] = Math.max(rowContent[row - 1], Math.ceil(heightPerRow));
		}
	}

	const columnSizes = sizeTracks(
		fullColumnTracks,
		columnContent,
		contentWidth,
		columnGap,
	);
	const rowSizes = sizeTracks(fullRowTracks, rowContent, contentHeight, rowGap);

	const columnOffsets: number[] = [];
	{
		let offset = 0;

		for (const size of columnSizes) {
			columnOffsets.push(offset);
			offset += size + columnGap;
		}
	}

	const rowOffsets: number[] = [];
	{
		let offset = 0;

		for (const size of rowSizes) {
			rowOffsets.push(offset);
			offset += size + rowGap;
		}
	}

	const gridWidth =
		columnSizes.length > 0
			? columnOffsets[columnOffsets.length - 1] + columnSizes[columnSizes.length - 1]
			: 0;
	const gridHeight =
		rowSizes.length > 0
			? rowOffsets[rowOffsets.length - 1] + rowSizes[rowSizes.length - 1]
			: 0;

	// The grid container is sized by its tracks unless the user set the size
	if (typeof style.width === 'undefined') {
		yogaNode.setWidth(
			gridWidth + padding.left + padding.right + border.left + border.right,
		);
	}

	if (typeof style.height === 'undefined') {
		yogaNode.setHeight(
			gridHeight + padding.top + padding.bottom + border.top + border.bottom,
		);
	}

	// Place each item in its cell
	for (let i = 0; i < items.length; i++) {
		const item = items[i];
		const cell = cells[i];
		const columnSpan = cell.colEnd - cell.colStart + 1;
		const rowSpan = cell.rowEnd - cell.rowStart + 1;

		let cellWidth = 0;

		for (let column = cell.colStart; column <= cell.colEnd; column++) {
			cellWidth += columnSizes[column - 1];
		}

		cellWidth += columnGap * (columnSpan - 1);

		let cellHeight = 0;

		for (let row = cell.rowStart; row <= cell.rowEnd; row++) {
			cellHeight += rowSizes[row - 1];
		}

		cellHeight += rowGap * (rowSpan - 1);

		const itemWidth = explicitSize(item.node.style.width, contentWidth) ?? cellWidth;
		const itemHeight =
			explicitSize(item.node.style.height, contentHeight) ?? cellHeight;

		const x = border.left + padding.left + columnOffsets[cell.colStart - 1];
		const y = border.top + padding.top + rowOffsets[cell.rowStart - 1];

		item.yoga.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
		item.yoga.setPosition(Yoga.EDGE_LEFT, x);
		item.yoga.setPosition(Yoga.EDGE_TOP, y);
		item.yoga.setPosition(Yoga.EDGE_RIGHT, Number.NaN);
		item.yoga.setPosition(Yoga.EDGE_BOTTOM, Number.NaN);
		item.yoga.setWidth(itemWidth);
		item.yoga.setHeight(itemHeight);

		item.node.internal_gridItem = true;
	}
};

// Restore flow layout for an item whose parent stopped being a grid container
const resetGridItem = (node: DOMElement): void => {
	node.internal_gridItem = false;

	const yoga = node.yogaNode;

	if (!yoga) {
		return;
	}

	if (typeof node.style.width === 'undefined') {
		yoga.setWidthAuto();
	}

	if (typeof node.style.height === 'undefined') {
		yoga.setHeightAuto();
	}

	const edges: Array<[keyof typeof Yoga.EDGE_LEFT, 'left' | 'top' | 'right' | 'bottom']> = [
		[Yoga.EDGE_LEFT, 'left'],
		[Yoga.EDGE_TOP, 'top'],
		[Yoga.EDGE_RIGHT, 'right'],
		[Yoga.EDGE_BOTTOM, 'bottom'],
	];

	for (const [edge, property] of edges) {
		if (typeof node.style[property] === 'undefined') {
			yoga.setPosition(edge, Number.NaN);
		}
	}

	if (node.style.position === 'absolute') {
		yoga.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
	} else if (node.style.position === 'static') {
		yoga.setPositionType(Yoga.POSITION_TYPE_STATIC);
	} else {
		yoga.setPositionType(Yoga.POSITION_TYPE_RELATIVE);
	}
};

const layoutGrid = (rootNode: DOMElement): void => {
	if (!rootNode.yogaNode) {
		return;
	}

	const containers: DOMElement[] = [];
	const staleItems: DOMElement[] = [];

	// Visit children first so nested grids are laid out before their parent
	// measures them
	const visit = (node: DOMElement): void => {
		for (const child of node.childNodes) {
			if (child.nodeName === '#text' || !child.yogaNode) {
				continue;
			}

			const element = child as DOMElement;

			visit(element);

			if (isGridContainer(element)) {
				containers.push(element);
			} else if (element.internal_gridItem) {
				staleItems.push(element);
			}
		}
	};

	visit(rootNode);

	if (rootNode.internal_gridItem) {
		staleItems.push(rootNode);
	}

	if (containers.length === 0 && staleItems.length === 0) {
		return;
	}

	// Reset stale items first, so containers that stopped being grids measure
	// their (now flow-laid-out) children correctly
	for (const item of staleItems) {
		resetGridItem(item);
	}

	for (const container of containers) {
		layoutGridContainer(container);
	}

	// Grid containers got explicit sizes and their items absolute positions —
	// re-lay out from the root so these propagate to ancestor elements
	rootNode.yogaNode.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
};

export default layoutGrid;
