content = '''import Yoga, {type Node as YogaNode} from 'yoga-layout';
import {type DOMElement} from './dom.js';

/*
Grid layout for elements with `display: grid`.

Yoga doesn't support grid layout, so after the regular flexbox pass this module:
1. Finds all grid containers (deepest first).
2. For each container, measures the natural size of each item, computes track
   sizes and item cells, then overrides each item's Yoga node with an absolute
   position and size, and gives the container an explicit width/height when the
   user hasn't set one.
3. Restores flow layout for items whose parent stopped being a grid container.
4. Re-lays out from the root so grid sizes propagate to ancestor elements.
*/

type Track =
	| {type: 'fixed'; size: number}
	| {type: 'fr'; size: number}
	| {type: 'auto'}
	| {type: 'minmaxFixed'; min: number; max: number}
	| {type: 'minmaxFr'; min: number; fr: number};

const group = (match: RegExpExecArray, index: number): string =>
	match[index] ?? '';

const parseTrack = (token: string): Track => {
	const track = token.trim();

	if (track === 'auto') {
		return {type: 'auto'};
	}

	const fr = /^(\\d+(?:\\.\\d+)?)fr$/.exec(track);

	if (fr) {
		return {type: 'fr', size: Number.parseFloat(group(fr, 1))};
	}

	if (/^\\d+(?:\\.\\d+)?$/.test(track)) {
		return {type: 'fixed', size: Math.floor(Number.parseFloat(track))};
	}

	const minmax = /^minmax\\(\\s*([^,]+?)\\s*,\\s*([^)]+?)\\s*\\)$/.exec(track);

	if (minmax) {
		const min = Math.max(
			0,
			Math.floor(Number.parseFloat(group(minmax, 1).trim())),
		);
		const maxFr = /^(\\d+(?:\\.\\d+)?)fr$/.exec(group(minmax, 2).trim());

		if (maxFr) {
			return {type: 'minmaxFr', min, fr: Number.parseFloat(group(maxFr, 1))};
		}

		const max = Math.max(
			min,
			Math.floor(Number.parseFloat(group(minmax, 2).trim())),
		);
		return {type: 'minmaxFixed', min, max};
	}

	// Unknown track size — treat as `auto`
	return {type: 'auto'};
};

const parseTracks = (template: string | undefined): Track[] => {
	if (!template) {
		return [];
	}

	const trimmed = template.trim();

	if (trimmed === '') {
		return [];
	}

	return trimmed
		.split(/\\s+/)
		.map(token => (token === '' ? {type: 'auto' as const} : parseTrack(token)));
};

const trackFr = (track: Track): number => {
	switch (track.type) {
		case 'fr':
			return track.size;

		case 'minmaxFr':
			return track.fr;

		default:
			return 0;
	}
};

// Size each track in pixels. Fixed, `minmax` with a definite max, and `auto`
// tracks take their base size first; whatever space is left is then
// distributed proportionally among `fr` tracks (the max of a `minmax` track or
// a plain `fr` track).
const sizeTracks = (
	tracks: Track[],
	contentSizes: number[],
	space: number,
	gap: number,
): number[] => {
	const count = tracks.length;
	const sizes = new Array<number>(count);
	let baseTotal = 0;

	for (let i = 0; i < count; i++) {
		const track = tracks[i]!;

		switch (track.type) {
			case 'fixed':
				sizes[i] = track.size;
				break;

			case 'minmaxFixed':
				// A definite max makes the track behave as a fixed-size one
				sizes[i] = track.max;
				break;

			case 'auto':
				sizes[i] = Math.max(0, Math.floor(contentSizes[i] ?? 0));
				break;

			case 'fr':
				sizes[i] = 0;
				break;

			case 'minmaxFr':
				sizes[i] = track.min;
				break;
		}

		baseTotal += sizes[i];
	}

	const gapTotal = count > 1 ? gap * (count - 1) : 0;
	const remaining = Math.max(0, Math.floor(space) - baseTotal - gapTotal);

	if (remaining > 0) {
		const totalFr = tracks.reduce((sum, track) => sum + trackFr(track), 0);

		if (totalFr > 0) {
			const shares = new Array<number>(count).fill(0);
			let allocated = 0;

			for (let i = 0; i < count; i++) {
				const weight = trackFr(tracks[i]!);

				if (weight <= 0) {
					continue;
				}

				const exact = (remaining * weight) / totalFr;
				shares[i] = Math.floor(exact);
				allocated += shares[i];
			}

			// Largest-remainder method so the shares add up exactly to `remaining`
			const leftover = remaining - allocated;

			if (leftover > 0) {
				const order = tracks
					.map((_, index) => index)
					.filter(index => trackFr(tracks[index]!) > 0)
					.sort((a, b) => {
						const remainderA =
							(remaining * trackFr(tracks[a]!)) / totalFr - shares[a];
						const remainderB =
							(remaining * trackFr(tracks[b]!)) / totalFr - shares[b];

						if (remainderB !== remainderA) {
							return remainderB - remainderA;
						}

						return a - b;
					});

				for (const index of order.slice(0, leftover)) {
					shares[index]++;
				}
			}

			for (let i = 0; i < count; i++) {
				sizes[i]! += shares[i]!;
			}
		}
	}

	return sizes;
};

type Placement = {
	start: number;
	end: number;
};

const parsePlacement = (
	value: string | number | undefined,
): Placement | undefined => {
	if (value === undefined || value === '') {
		return undefined;
	}

	let start: number;
	let end: number;

	if (typeof value === 'number') {
		start = Math.max(1, Math.floor(value));
		end = start;
	} else {
		const range = /^\\s*(\\d+)\\s*\\/\\s*(\\d+)\\s*$/.exec(value);

		if (range) {
			start = Math.max(1, Number.parseInt(group(range, 1), 10));
			end = Math.max(start, Number.parseInt(group(range, 2), 10));
		} else {
			const index = Number.parseInt(value, 10);

			if (Number.isNaN(index)) {
				return undefined;
			}

			start = Math.max(1, index);
			end = start;
		}
	}

	return {start, end};
};

// A single size (`width` or `height`) the user set explicitly on a grid item.
// Percentages are resolved against the container's content box.
const explicitSize = (
	value: number | string | undefined,
	reference: number,
): number | undefined => {
	if (typeof value === 'number') {
		return Math.max(0, Math.floor(value));
	}

	if (typeof value === 'string') {
		const percent = Number.parseFloat(value);

		if (Number.isFinite(percent)) {
			return Math.max(0, Math.floor((reference * percent) / 100));
		}
	}

	return undefined;
};

const isGridContainer = (node: DOMElement): boolean =>
	node.style.display === 'grid' &&
	node.yogaNode !== undefined &&
	node.yogaNode.getDisplay() !== Yoga.DISPLAY_NONE;

type Item = {
	node: DOMElement;
	yoga: YogaNode;
	column: Placement | undefined;
	row: Placement | undefined;
	width: number;
	height: number;
};

type Cell = {
	rowStart: number;
	rowEnd: number;
	colStart: number;
	colEnd: number;
};

const layoutGridContainer = (container: DOMElement): void => {
	const yogaNode = container.yogaNode!;
	const style = container.style;

	const columnTracks = parseTracks(style.gridTemplateColumns);
	const rowTracks = parseTracks(style.gridTemplateRows);

	const columnGap = Math.max(0, style.columnGap ?? style.gap ?? 0);
	const rowGap = Math.max(0, style.rowGap ?? style.gap ?? 0);

	const padding = {
		top: yogaNode.getComputedPadding(Yoga.EDGE_TOP),
		right: yogaNode.getComputedPadding(Yoga.EDGE_RIGHT),
		bottom: yogaNode.getComputedPadding(Yoga.EDGE_BOTTOM),
		left: yogaNode.getComputedPadding(Yoga.EDGE_LEFT),
	};

	const border = {
		top: yogaNode.getComputedBorder(Yoga.EDGE_TOP),
		right: yogaNode.getComputedBorder(Yoga.EDGE_RIGHT),
		bottom: yogaNode.getComputedBorder(Yoga.EDGE_BOTTOM),
		left: yogaNode.getComputedBorder(Yoga.EDGE_LEFT),
	};

	const contentWidth = Math.max(
		0,
		yogaNode.getComputedWidth() -
			padding.left -
			padding.right -
			border.left -
			border.right,
	);

	const contentHeight = Math.max(
		0,
		yogaNode.getComputedHeight() -
			padding.top -
			padding.bottom -
			border.top -
			border.bottom,
	);

	// Collect grid items and measure their natural (content) size
	const items: Item[] = [];

	for (const child of container.childNodes) {
		if (child.nodeName === '#text' || !child.yogaNode) {
			continue;
		}

		const element = child as DOMElement;

		if (element.yogaNode.getDisplay() === Yoga.DISPLAY_NONE) {
			continue;
		}

		const item: Item = {
			node: element,
			yoga: element.yogaNode,
			column: parsePlacement(element.style.gridColumn),
			row: parsePlacement(element.style.gridRow),
			width: 0,
			height: 0,
		};

		// A previous grid pass may have sized this item to its cell — restore
		// auto sizing so we measure its content. Nested grid containers are
		// skipped: their own pass (already run, since nested containers are
		// processed first) just set their final explicit size.
		if (element.internal_gridItem && !isGridContainer(element)) {
			if (typeof element.style.width === 'undefined') {
				item.yoga.setWidthAuto();
			}

			if (typeof element.style.height === 'undefined') {
				item.yoga.setHeightAuto();
			}
		}

		item.yoga.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
		item.width = Math.max(0, Math.floor(item.yoga.getComputedWidth()));
		item.height = Math.max(0, Math.floor(item.yoga.getComputedHeight()));

		items.push(item);
	}

	// Place the items on the grid: explicit placement wins, the rest flows
	// row by row (left to right, top to bottom)
	const wrapColumn = Math.max(columnTracks.length, 1);

	const occupied = new Set<string>();
	const cellKey = (row: number, column: number): string => `${row}:${column}`;

	const isFree = (
		startRow: number,
		endRow: number,
		startColumn: number,
		endColumn: number,
	): boolean => {
		for (let row = startRow; row <= endRow; row++) {
			for (let column = startColumn; column <= endColumn; column++) {
				if (occupied.has(cellKey(row, column))) {
					return false;
				}
			}
		}

		return true;
	};

	const cells: Cell[] = new Array<Cell>(items.length);
	let cursorRow = 1;
	let cursorColumn = 1;

	for (let i = 0; i < items.length; i++) {
		const item = items[i]!;
		let cell: Cell;

		if (item.column && item.row) {
			cell = {
				colStart: item.column.start,
				colEnd: item.column.end,
				rowStart: item.row.start,
				rowEnd: item.row.end,
			};
		} else if (item.column) {
			const {start: colStart, end: colEnd} = item.column;
			let row = cursorRow;

			while (!isFree(row, row, colStart, colEnd)) {
				row++;
			}

			cell = {colStart, colEnd, rowStart: row, rowEnd: row};
		} else if (item.row) {
			const {start: rowStart, end: rowEnd} = item.row;
			let column = cursorColumn > wrapColumn ? 1 : cursorColumn;

			while (column < wrapColumn && !isFree(rowStart, rowEnd, column, column)) {
				column++;
			}

			cell = {colStart: column, colEnd: column, rowStart, rowEnd};
