	// Count the tracks — auto-generated ones are created as needed
	let numColumns = columnTracks.length;
	let numRows = rowTracks.length;

	for (const cell of cells) {
		numColumns = Math.max(numColumns, cell.colEnd);
		numRows = Math.max(numRows, cell.rowEnd);
	}

	const fullColumnTracks: Track[] = [];

	for (let i = 0; i < numColumns; i++) {
		fullColumnTracks.push(columnTracks[i] ?? {type: 'auto'});
	}

	const fullRowTracks: Track[] = [];

	for (let i = 0; i < numRows; i++) {
		fullRowTracks.push(rowTracks[i] ?? {type: 'auto'});
