	);
	const rowSizes = sizeTracks(fullRowTracks, rowContent, contentHeight, rowGap);

	const columnOffsets: number[] = [];
	{
		let offset = 0;

		for (const size of columnSizes) {
			columnOffsets.push(offset);
			offset += size + columnGap;
		}
	}

	const rowOffsets: number[] = [];
	{
		let offset = 0;

		for (const size of rowSizes) {
			rowOffsets.push(offset);
			offset += size + rowGap;
