+
+	if (typeof value === 'number') {
+		start = Math.max(1, Math.floor(value));
+		end = start;
+	} else {
+		const range = /^\s*(\d+)\s*\/\s*(\d+)\s*$/.exec(value);
+
+		if (range) {
+			start = Math.max(1, Number.parseInt(group(range, 1), 10));
+			end = Math.max(start, Number.parseInt(group(range, 2), 10));
+		} else {
+			const index = Number.parseInt(value, 10);
+
+			if (Number.isNaN(index)) {
+				return undefined;
+			}
+
+			start = Math.max(1, index);
+			end = start;
+		}
+	}
+
+	return {start, end};
+};
+
+// A single size (`width` or `height`) the user set explicitly on a grid item.
+// Percentages are resolved against the container's content box.
+const explicitSize = (
+	value: number | string | undefined,
+	reference: number,
+): number | undefined => {
+	if (typeof value === 'number') {
+		return Math.max(0, Math.floor(value));
+	}
+
+	if (typeof value === 'string') {
+		const percent = Number.parseFloat(value);
+
+		if (Number.isFinite(percent)) {
+			return Math.max(0, Math.floor((reference * percent) / 100));
+		}
+	}
+
+	return undefined;
+};
+
+const isGridContainer = (node: DOMElement): boolean =>
+	node.style.display === 'grid' &&
+	node.yogaNode !== undefined &&
+	node.yogaNode.getDisplay() !== Yoga.DISPLAY_NONE;
+
+type Item = {
+	node: DOMElement;
+	yoga: YogaNode;
+	column: Placement | undefined;
+	row: Placement | undefined;
+	width: number;
+	height: number;
+	finalWidth: number;
+};
+
+type Cell = {
+	rowStart: number;
+	rowEnd: number;
+	colStart: number;
+	colEnd: number;
+};
+
+const layoutGridContainer = (container: DOMElement): void => {
+	const yogaNode = container.yogaNode!;
+	const {style} = container;
+
+	const columnTracks = parseTracks(style.gridTemplateColumns);
+	const rowTracks = parseTracks(style.gridTemplateRows);
+
+	const columnGap = Math.max(0, style.columnGap ?? style.gap ?? 0);
+	const rowGap = Math.max(0, style.rowGap ?? style.gap ?? 0);
+
+	const padding = {
+		top: yogaNode.getComputedPadding(Yoga.EDGE_TOP),
+		right: yogaNode.getComputedPadding(Yoga.EDGE_RIGHT),
+		bottom: yogaNode.getComputedPadding(Yoga.EDGE_BOTTOM),
+		left: yogaNode.getComputedPadding(Yoga.EDGE_LEFT),
+	};
+
+	const border = {
+		top: yogaNode.getComputedBorder(Yoga.EDGE_TOP),
+		right: yogaNode.getComputedBorder(Yoga.EDGE_RIGHT),
+		bottom: yogaNode.getComputedBorder(Yoga.EDGE_BOTTOM),
+		left: yogaNode.getComputedBorder(Yoga.EDGE_LEFT),
+	};
+
+	const contentWidth = Math.max(
+		0,
+		yogaNode.getComputedWidth() -
+			padding.left -
+			padding.right -
+			border.left -
+			border.right,
+	);
+
+	const contentHeight = Math.max(
+		0,
+		yogaNode.getComputedHeight() -
+			padding.top -
+			padding.bottom -
+			border.top -
+			border.bottom,
+	);
+
+	// Collect grid items and measure their natural (content) size
+	const items: Item[] = [];
+
+	for (const child of container.childNodes) {
+		if (child.nodeName === '#text' || !child.yogaNode) {
+			continue;
+		}
+
+		const element = child;
+		const elementYogaNode = child.yogaNode;
+
+		if (elementYogaNode.getDisplay() === Yoga.DISPLAY_NONE) {
+			continue;
+		}
+
+		const item: Item = {
+			node: element,
+			yoga: elementYogaNode,
+			column: parsePlacement(element.style.gridColumn),
+			row: parsePlacement(element.style.gridRow),
+			width: 0,
+			height: 0,
+			finalWidth: 0,
+		};
+
+		// A previous grid pass may have sized this item to its cell — restore
+		// auto sizing so we measure its content. Nested grid containers are
+		// skipped: their own pass (already run, since nested containers are
+		// processed first) just set their final explicit size.
+		if (element.internal_gridItem && !isGridContainer(element)) {
+			if (element.style.width === undefined) {
+				item.yoga.setWidthAuto();
+			}
+
+			if (element.style.height === undefined) {
+				item.yoga.setHeightAuto();
+			}
+		}
+
+		item.yoga.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+		item.width = Math.max(0, Math.floor(item.yoga.getComputedWidth()));
+		item.height = Math.max(0, Math.floor(item.yoga.getComputedHeight()));
+
+		items.push(item);
+	}
+
+	// Place the items on the grid: explicit placement wins, the rest flows
+	// row by row (left to right, top to bottom)
+	const wrapColumn = Math.max(columnTracks.length, 1);
+
+	const occupied = new Set<string>();
+	const cellKey = (row: number, column: number): string => `${row}:${column}`;
+
+	const isFree = (
+		startRow: number,
+		endRow: number,
+		startColumn: number,
+		endColumn: number,
+	): boolean => {
+		for (let row = startRow; row <= endRow; row++) {
+			for (let column = startColumn; column <= endColumn; column++) {
+				if (occupied.has(cellKey(row, column))) {
+					return false;
+				}
+			}
+		}
+
+		return true;
+	};
+
+	const cells: Cell[] = Array.from({length: items.length});
+	let cursorRow = 1;
+	let cursorColumn = 1;
+
+	for (let i = 0; i < items.length; i++) {
+		const item = items[i]!;
+		let cell: Cell;
+
+		if (item.column && item.row) {
+			cell = {
+				colStart: item.column.start,
+				colEnd: item.column.end,
+				rowStart: item.row.start,
+				rowEnd: item.row.end,
+			};
+		} else if (item.column) {
+			const {start: colStart, end: colEnd} = item.column;
+			let row = cursorRow;
+
+			while (!isFree(row, row, colStart, colEnd)) {
+				row++;
+			}
+
+			cell = {colStart, colEnd, rowStart: row, rowEnd: row};
+		} else if (item.row) {
+			const {start: rowStart, end: rowEnd} = item.row;
+			let column = cursorColumn > wrapColumn ? 1 : cursorColumn;
+			// The row is fixed, so if all known columns are taken the item
+			// spills into an auto-generated column
+			const limit = wrapColumn + items.length;
+
+			while (column <= limit && !isFree(rowStart, rowEnd, column, column)) {
+				column++;
+			}
+
+			if (column > limit) {
+				column = 1;
+			}
+
+			cell = {colStart: column, colEnd: column, rowStart, rowEnd};
+		} else {
+			let rowStart = cursorRow;
+			let colStart = cursorColumn;
+
+			while (
+				occupied.has(cellKey(rowStart, colStart)) ||
+				colStart > wrapColumn
+			) {
+				colStart++;
+
+				if (colStart > wrapColumn) {
+					colStart = 1;
+					rowStart++;
+				}
+			}
+
+			cell = {colStart, colEnd: colStart, rowStart, rowEnd: rowStart};
+		}
+
+		for (let row = cell.rowStart; row <= cell.rowEnd; row++) {
+			for (let column = cell.colStart; column <= cell.colEnd; column++) {
+				occupied.add(cellKey(row, column));
+			}
+		}
+
+		cells[i] = cell;
+
+		// Only fully auto-placed items advance the cursor; explicit
+		// placement doesn't move it (occupied cells are skipped by the
+		// auto-placement search)
+		if (!item.column && !item.row) {
+			cursorRow = cell.rowStart;
+			cursorColumn = cell.colEnd + 1;
+
+			if (cursorColumn > wrapColumn) {
+				cursorColumn = 1;
+				cursorRow++;
+			}
+		}
+	}
+
+	// Count the tracks — auto-generated ones are created as needed
+	let numColumns = columnTracks.length;
+	let numRows = rowTracks.length;
+
+	for (const cell of cells) {
+		numColumns = Math.max(numColumns, cell.colEnd);
+		numRows = Math.max(numRows, cell.rowEnd);
+	}
+
+	const fullColumnTracks: Track[] = [];
+
+	for (let i = 0; i < numColumns; i++) {
+		fullColumnTracks.push(columnTracks[i] ?? {type: 'auto'});
+	}
+
+	const fullRowTracks: Track[] = [];
+
+	for (let i = 0; i < numRows; i++) {
+		fullRowTracks.push(rowTracks[i] ?? {type: 'auto'});
+	}
+
+	// Content size of each column, used by `auto` columns. Items spanning
+	// multiple columns contribute their size divided evenly across them.
+	const columnContent = Array.from({length: numColumns}, () => 0);
+
+	for (const [i, item] of items.entries()) {
+		const cell = cells[i]!;
+		const columnSpan = cell.colEnd - cell.colStart + 1;
+		const widthPerColumn = columnSpan > 0 ? item.width / columnSpan : 0;
+
+		for (let column = cell.colStart; column <= cell.colEnd; column++) {
+			columnContent[column - 1] = Math.max(
+				columnContent[column - 1]!,
+				Math.ceil(widthPerColumn),
+			);
+		}
+	}
+
+	const columnSizes = sizeTracks(
+		fullColumnTracks,
+		columnContent,
+		contentWidth,
+		columnGap,
+	);
+
+	// Size each item to its cell and measure its height at that width, so
+	// `auto` rows account for text that wraps in narrower columns
+	const rowContent = Array.from({length: numRows}, () => 0);
+
+	for (const [i, item_] of items.entries()) {
+		const item = item_;
+		const cell = cells[i]!;
+		const columnSpan = cell.colEnd - cell.colStart + 1;
+		const rowSpan = cell.rowEnd - cell.rowStart + 1;
+
+		let cellWidth = 0;
+
+		for (let column = cell.colStart; column <= cell.colEnd; column++) {
+			cellWidth += columnSizes[column - 1] ?? 0;
+		}
+
+		cellWidth += columnGap * (columnSpan - 1);
+
+		const explicitWidth = explicitSize(item.node.style.width, contentWidth);
+		const itemWidth = explicitWidth ?? cellWidth;
+		item.finalWidth = itemWidth;
+
+		if (
+			item.node.style.height === undefined &&
+			!isGridContainer(item.node) &&
+			itemWidth < item.width
+		) {
+			item.yoga.setWidth(itemWidth);
+			item.yoga.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+			item.height = Math.max(0, Math.floor(item.yoga.getComputedHeight()));
+		} else if (item.node.style.height !== undefined) {
+			item.height = explicitSize(item.node.style.height, contentHeight) ?? 0;
+		}
+
+		const heightPerRow = rowSpan > 0 ? item.height / rowSpan : 0;
+
+		for (let row = cell.rowStart; row <= cell.rowEnd; row++) {
+			rowContent[row - 1] = Math.max(
+				rowContent[row - 1]!,
+				Math.ceil(heightPerRow),
+			);
+		}
+	}
+
+	const rowSizes = sizeTracks(fullRowTracks, rowContent, contentHeight, rowGap);
+
+	const columnOffsets: number[] = [];
+	{
+		let offset = 0;
+
+		for (const size of columnSizes) {
+			columnOffsets.push(offset);
+			offset += size + columnGap;
+		}
+	}
+
+	const rowOffsets: number[] = [];
+	{
+		let offset = 0;
+
+		for (const size of rowSizes) {
+			rowOffsets.push(offset);
+			offset += size + rowGap;
+		}
+	}
+
+	const gridWidth =
+		columnSizes.length > 0
+			? (columnOffsets.at(-1) ?? 0) + (columnSizes.at(-1) ?? 0)
+			: 0;
+	const gridHeight =
+		rowSizes.length > 0 ? (rowOffsets.at(-1) ?? 0) + (rowSizes.at(-1) ?? 0) : 0;
+
+	// The grid container is sized by its tracks unless the user set the size.
+	// The flexbox pass may have given the container more space than the tracks
+	// need (for example when it's stretched by its parent) — keep that size so
+	// the tracks stay aligned to the start of the container.
+	if (style.width === undefined) {
+		const gridBoxWidth =
+			gridWidth + padding.left + padding.right + border.left + border.right;
+
+		yogaNode.setWidth(Math.max(gridBoxWidth, yogaNode.getComputedWidth()));
+	}
+
+	if (style.height === undefined) {
+		const gridBoxHeight =
+			gridHeight + padding.top + padding.bottom + border.top + border.bottom;
+
+		yogaNode.setHeight(Math.max(gridBoxHeight, yogaNode.getComputedHeight()));
+	}
+
+	// Remember that this pass gave the container explicit sizing, so it can
+	// be restored to auto sizing if the node stops being a grid container
+	container.internal_gridContainer = true;
+
+	// Place each item in its cell
+	for (const [i, item_] of items.entries()) {
+		const item = item_;
+		const cell = cells[i]!;
+		const rowSpan = cell.rowEnd - cell.rowStart + 1;
+
+		let cellHeight = 0;
+
+		for (let row = cell.rowStart; row <= cell.rowEnd; row++) {
+			cellHeight += rowSizes[row - 1] ?? 0;
+		}
+
+		cellHeight += rowGap * (rowSpan - 1);
+
+		// `item.height` was measured at the item's final width during the
+		// sizing phase; a user-set height takes precedence over the cell
+		const itemWidth = item.finalWidth;
+		const itemHeight =
+			explicitSize(item.node.style.height, contentHeight) ?? cellHeight;
+
+		// Yoga places absolutely-positioned nodes relative to the parent's
+		// padding box, so only the padding is part of the offset
+		const x = padding.left + (columnOffsets[cell.colStart - 1] ?? 0);
+		const y = padding.top + (rowOffsets[cell.rowStart - 1] ?? 0);
+
+		item.yoga.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+		item.yoga.setPosition(Yoga.EDGE_LEFT, x);
+		item.yoga.setPosition(Yoga.EDGE_TOP, y);
+		item.yoga.setPosition(Yoga.EDGE_RIGHT, Number.NaN);
+		item.yoga.setPosition(Yoga.EDGE_BOTTOM, Number.NaN);
+		item.yoga.setWidth(itemWidth);
+		item.yoga.setHeight(itemHeight);
+
+		item.node.internal_gridItem = true;
+	}
+};
+
+// Restore flow layout for an item whose parent stopped being a grid container
+const resetGridItem = (node: DOMElement): void => {
+	node.internal_gridItem = false;
+
+	const yoga = node.yogaNode;
+
+	if (!yoga) {
+		return;
+	}
+
+	if (node.style.width === undefined) {
+		yoga.setWidthAuto();
+	}
+
+	if (node.style.height === undefined) {
+		yoga.setHeightAuto();
+	}
+
+	const edges: Array<[Edge, 'left' | 'top' | 'right' | 'bottom']> = [
+		[Yoga.EDGE_LEFT, 'left'],
+		[Yoga.EDGE_TOP, 'top'],
+		[Yoga.EDGE_RIGHT, 'right'],
+		[Yoga.EDGE_BOTTOM, 'bottom'],
+	];
+
+	for (const [edge, property] of edges) {
+		if (node.style[property] === undefined) {
+			yoga.setPosition(edge, Number.NaN);
+		}
+	}
+
+	if (node.style.position === 'absolute') {
+		yoga.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+	} else if (node.style.position === 'static') {
+		yoga.setPositionType(Yoga.POSITION_TYPE_STATIC);
+	} else {
+		yoga.setPositionType(Yoga.POSITION_TYPE_RELATIVE);
+	}
+};
+
+// Restore auto sizing for a container that stopped being a grid
+const resetGridContainer = (node: DOMElement): void => {
+	node.internal_gridContainer = false;
+
+	const yoga = node.yogaNode;
+
+	if (!yoga) {
+		return;
+	}
+
+	if (node.style.width === undefined) {
+		yoga.setWidthAuto();
+	}
+
+	if (node.style.height === undefined) {
+		yoga.setHeightAuto();
+	}
+};
+
+const layoutGrid = (rootNode: DOMElement): void => {
+	if (!rootNode.yogaNode) {
+		return;
+	}
+
+	const containers: DOMElement[] = [];
+	const staleItems: DOMElement[] = [];
+	const staleContainers: DOMElement[] = [];
+
+	// Visit children first so nested grids are laid out before their parent
+	// measures them
+	const visit = (node: DOMElement): void => {
+		for (const child of node.childNodes) {
+			if (child.nodeName === '#text' || !child.yogaNode) {
+				continue;
+			}
+
+			const element = child;
+
+			visit(element);
+
+			if (isGridContainer(element)) {
+				containers.push(element);
+			} else {
+				if (element.internal_gridItem) {
+					staleItems.push(element);
+				}
+
+				if (element.internal_gridContainer) {
+					staleContainers.push(element);
+				}
+			}
+		}
+	};
+
+	visit(rootNode);
+
+	if (rootNode.internal_gridItem) {
+		staleItems.push(rootNode);
+	}
+
+	if (rootNode.internal_gridContainer) {
+		staleContainers.push(rootNode);
+	}
+
+	if (
+		containers.length === 0 &&
+		staleItems.length === 0 &&
+		staleContainers.length === 0
+	) {
+		return;
+	}
+
+	// Reset stale items and containers first, so remaining containers measure
+	// their (now flow-laid-out) children correctly
+	for (const item of staleItems) {
+		resetGridItem(item);
+	}
+
+	for (const container of staleContainers) {
+		resetGridContainer(container);
+	}
+
+	for (const container of containers) {
+		layoutGridContainer(container);
+	}
+
+	// Grid containers got explicit sizes and their items absolute positions —
+	// re-lay out from the root so these propagate to ancestor elements
+	rootNode.yogaNode.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+};
+
+export default layoutGrid;
