+import React from 'react';
+import test from 'ava';
+import {Box, Text} from '../src/index.js';
+import {
+	renderToString,
+	renderToStringAsync,
+} from './helpers/render-to-string.js';
+import {renderAsync} from './helpers/test-renderer.js';
+
+test('renders a grid with fixed columns', t => {
+	const output = renderToString(
+		<Box display="grid" gridTemplateColumns="3 3">
+			<Box>
+				<Text>A</Text>
+			</Box>
+			<Box>
+				<Text>B</Text>
+			</Box>
+			<Box>
+				<Text>C</Text>
+			</Box>
+		</Box>,
+	);
+
+	t.is(output, 'A  B\nC');
+});
+
+test('creates rows automatically when gridTemplateRows is omitted', t => {
+	const output = renderToString(
+		<Box display="grid" gridTemplateColumns="2">
+			<Box>
+				<Text>A</Text>
+			</Box>
+			<Box>
+				<Text>B</Text>
+			</Box>
+			<Box>
+				<Text>C</Text>
+			</Box>
+		</Box>,
+	);
+
+	t.is(output, 'A\nB\nC');
+});
+
+test('distributes fractional columns', t => {
+	const output = renderToString(
+		<Box width={10} display="grid" gridTemplateColumns="1fr 1fr">
+			<Box>
+				<Text>A</Text>
+			</Box>
+			<Box>
+				<Text>B</Text>
+			</Box>
+		</Box>,
+	);
+
+	t.is(output, 'A    B');
+});
+
