+
+	t.is(instance.getOutput(), 'A    B');
+
+	await instance.rerenderAsync(
+		<Box width={10} display="grid" gridTemplateColumns="1fr 1fr">
+			<Box>
+				<Text>AB</Text>
+			</Box>
+			<Box>
+				<Text>CD</Text>
+			</Box>
+		</Box>,
+	);
+
+	t.is(instance.getOutput(), 'AB   CD');
+});
